sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var state = g_form.getValue('state');
    if (state == '1') { // replace 'new' with the actual value if needed
        g_form.setValue('email_subject', "Closing of case " + g_form.getValue('subject') + " - " + g_form.getValue('query_id'));
    } else if (state == '5' || state == '3' || state == '4') {
        var fields = g_form.getEditableFields();
        for (var i = 0; i < fields.length; i++) {
            g_form.setReadOnly(fields[i], true);
        }
    }

    // If user has ops_admin role, make assigned_to editable
    if (g_user.hasRole('x_hsb11_mss_trus_0.complaint_admin')) {
        g_form.setReadOnly('assigned_to', false);
    }
    //MSSTRUSTES-469
    g_form.setSectionDisplay('comments', false);

}
